"""find pick element"""
def find_peak(A: Any) -> object {
    if (A == []) {
        return None;
    }
    """helper recursive function""";
    def recursive(A: Any, left: Any = 0, right: Any = (len(A) - 1)) -> object {
        mid = (left + right) // 2;
        if (
            ((mid == 0) or (A[(mid - 1)] <= A[mid]))
            and ((mid == (len(A) - 1)) or (A[(mid + 1)] <= A[mid]))
        ) {
            return A[mid];
        }
        if (((mid - 1) >= 0) and (A[(mid - 1)] > A[mid])) {
            return recursive(A, left, (mid - 1));
        }
        return recursive(A, (mid + 1), right);
    }
    return recursive(A);
}

